      quantidade_objetos: 3,
      prioridade_fadiga: 'ANUNCIO_B',
      fadiga_alta: [
        {
          'NIVEL ANALISE': 'Anúncio',
          'NOME OBJETO': 'ANUNCIO_B',
          'SCORE FADIGA': 90,
          'CLASSIFICACAO FADIGA': 'FADIGA ALTA',
          'VARIACAO CTR LINK 3D VS BASELINE': -38,
          'VARIACAO CPC 3D VS BASELINE': 42,
          'VARIACAO CUSTO CONVERSA 3D VS BASELINE': 65
        }
      ],
      fadiga_moderada: [],
      observar: [
        { 'NIVEL ANALISE': 'Anúncio', 'NOME OBJETO': 'ANUNCIO_C', 'SCORE FADIGA': 30, 'CLASSIFICACAO FADIGA': 'OBSERVAR' }
      ],
      melhora: [
        {
          'NIVEL ANALISE': 'Anúncio',
          'NOME OBJETO': 'ANUNCIO_A',
          'SCORE FADIGA': 0,
          'CLASSIFICACAO FADIGA': 'MELHORA',
          'VARIACAO CTR LINK 3D VS BASELINE': 22,
          'VARIACAO CUSTO CONVERSA 3D VS BASELINE': -18
        }
      ],
      dados_insuficientes: []
    }
  }
}];

// Valida a entrada e reduz o payload antes da IA.
const entrada = $json || {};
const performance = entrada.performance;
const tendencia = entrada.tendencia;

if (!performance || !tendencia) {
  return [{ json: { status_pacote: 'PACOTE_INCOMPLETO', motivo: 'São necessários os blocos performance e tendencia.' } }];
}

if (performance.status_motor !== 'OK') {
  return [{ json: { status_pacote: 'SEM_PERFORMANCE', motivo: performance.mensagem || 'Motor de Performance não retornou OK.' } }];
}

if (tendencia.status_tendencia !== 'OK') {
  return [{ json: { status_pacote: 'SEM_TENDENCIA', motivo: tendencia.mensagem || 'Motor de Tendência não retornou OK.' } }];
}

const limitar = (valor, maximo = 5) => Array.isArray(valor) ? valor.slice(0, maximo) : [];

function compacto(objeto) {
  if (!objeto || typeof objeto !== 'object') return objeto;
  const saida = {};
  for (const [chave, valor] of Object.entries(objeto)) {
    if (valor === null || valor === undefined) continue;
    if (['string', 'number', 'boolean'].includes(typeof valor)) saida[chave] = valor;
  }
  return saida;
}

const pacote = {
  data_referencia: performance.data_referencia || tendencia.data_referencia || '',
  performance: {
    investimento_total: performance.investimento_total ?? null,
    conversas_iniciadas: performance.conversas_iniciadas ?? null,
    custo_medio_por_conversa: performance.custo_medio_por_conversa ?? null,
    score_tecnico_medio: performance.score_tecnico_medio ?? null,
    quantidade_registros: performance.quantidade_registros ?? null,
    melhores_resultados: limitar(performance.melhores_resultados).map(compacto),
    resultados_para_atencao: limitar(performance.resultados_para_atencao).map(compacto)
  },
  tendencia: {
    quantidade_objetos: tendencia.quantidade_objetos ?? null,
    prioridade_fadiga: tendencia.prioridade_fadiga ?? null,
    fadiga_alta: limitar(tendencia.fadiga_alta).map(compacto),
    fadiga_moderada: limitar(tendencia.fadiga_moderada).map(compacto),
    observar: limitar(tendencia.observar).map(compacto),
    melhora: limitar(tendencia.melhora).map(compacto),
    dados_insuficientes: limitar(tendencia.dados_insuficientes).map(compacto)
  }
};

return [{
  json: {
    status_pacote: 'OK',
    pacote_analise: pacote,
    tamanho_aproximado: JSON.stringify(pacote).length
  }
}];

// Monta o prompt. Nesta V3 não existe Structured Output Parser.
