// V3: parser manual. Não depende do Structured Output Parser do n8n.
const origem = $json || {};

let bruto =
  origem.text ??
  origem.output ??
  origem.response ??
  origem.content ??
  origem.message ??
  origem;

if (typeof bruto === 'object' && bruto !== null) {
  // Alguns modelos/nodes já podem retornar objeto.
  if (bruto.resumo_executivo || bruto.prioridades) {
    bruto = JSON.stringify(bruto);
  } else {
    // Procura um campo textual em estruturas comuns.
    const candidato =
      bruto.text ??
      bruto.output ??
      bruto.content ??
      bruto.message ??
      JSON.stringify(bruto);
    bruto = typeof candidato === 'string' ? candidato : JSON.stringify(candidato);
  }
}

let texto = String(bruto || '').trim();

// Remove cercas de código se o modelo ignorar a instrução.
texto = texto
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

// Extrai do primeiro { ao último } se houver texto extra.
const inicio = texto.indexOf('{');
const fim = texto.lastIndexOf('}');
if (inicio >= 0 && fim > inicio) {
  texto = texto.slice(inicio, fim + 1);
}

let analise;
try {
  analise = JSON.parse(texto);
} catch (erro) {
  return [{
    json: {
      status_analise_ia: 'JSON_INVALIDO',
      erro_parser: erro.message,
      resposta_bruta: String(bruto || '').slice(0, 12000)
    }
  }];
}

// Aceita eventual envelope { output: {...} }.
if (
  analise &&
  typeof analise === 'object' &&
  analise.output &&
  typeof analise.output === 'object'
) {
  analise = analise.output;
}

const lista = valor => Array.isArray(valor) ? valor : [];
const textoSeguro = (valor, padrao = '') =>
  valor === undefined || valor === null ? padrao : String(valor);

const acoesPermitidas = new Set([
  'MANTER',
  'OBSERVAR',
  'REVISAR_CRIATIVO',
  'REVISAR_PUBLICO',
  'REVISAR_OFERTA',
  'TESTAR_VARIACAO',
  'CANDIDATO_ESCALA',
  'REDUZIR_EXPOSICAO'
]);

const prioridades = lista(analise.prioridades)
  .slice(0, 5)
  .map((item, indice) => {
    const acaoRecebida = textoSeguro(item?.acao_recomendada, 'OBSERVAR')
      .trim()
      .toUpperCase();

    return {
      prioridade: Math.max(1, Number(item?.prioridade || indice + 1)),
      nivel: textoSeguro(item?.nivel, 'Não informado'),
      nome: textoSeguro(item?.nome, 'Não informado'),
      diagnostico: textoSeguro(item?.diagnostico),
      evidencias: lista(item?.evidencias).slice(0, 4).map(String),
      acao_recomendada: acoesPermitidas.has(acaoRecebida) ? acaoRecebida : 'OBSERVAR',
      motivo: textoSeguro(item?.motivo),
      prazo_reavaliacao_dias: Math.max(
        1,
        Math.min(30, Number(item?.prazo_reavaliacao_dias || 3))
      )
    };
  })
  .sort((a, b) => a.prioridade - b.prioridade);

const normalizada = {
  resumo_executivo: textoSeguro(analise.resumo_executivo),
  saude_conta: textoSeguro(analise.saude_conta, 'dados_insuficientes'),
  confianca_analise: textoSeguro(analise.confianca_analise, 'baixa'),
  prioridades,
  oportunidades: lista(analise.oportunidades).slice(0, 5),
  riscos: lista(analise.riscos).slice(0, 5),
  hipoteses_teste: lista(analise.hipoteses_teste).slice(0, 4),
  nao_fazer: lista(analise.nao_fazer).slice(0, 5)
};

return [{
  json: {
    status_analise_ia: 'OK',
    analise_ia: normalizada,
    parser_usado: 'CODE_MANUAL_V3'
  }
}];

// Converte a análise normalizada em briefing para o gestor.
const a = $json.analise_ia;
const blocos = [];

blocos.push(
  `ANÁLISE IA META ADS\n` +
  `Saúde da conta: ${String(a.saude_conta).toUpperCase()}\n` +
  `Confiança: ${String(a.confianca_analise).toUpperCase()}\n\n` +
  `${a.resumo_executivo}`
);

if (a.prioridades.length) {
  blocos.push(
    'PRIORIDADES\n' +
    a.prioridades.map(p =>
      `${p.prioridade}. ${p.nome} — ${p.acao_recomendada}\n` +
      `${p.diagnostico}\n` +
      `Evidências: ${p.evidencias.join(' | ')}\n` +
      `Reavaliar em: ${p.prazo_reavaliacao_dias} dia(s)`
    ).join('\n\n')
  );
}

if (a.oportunidades.length) {
  blocos.push(
    'OPORTUNIDADES\n' +
    a.oportunidades.map(x => `- ${x.nome || 'Sem nome'}: ${x.oportunidade || ''}`).join('\n')
  );
}

if (a.riscos.length) {
  blocos.push(
    'RISCOS\n' +
    a.riscos.map(x => `- ${x.nome || 'Sem nome'}: ${x.risco || ''}`).join('\n')
  );
}

if (a.hipoteses_teste.length) {
  blocos.push(
    'HIPÓTESES DE TESTE\n' +
    a.hipoteses_teste.map(x =>
      `- ${x.hipotese || ''}\n` +
      `  Mudança: ${x.mudanca || ''}\n` +
      `  Métrica: ${x.metrica_primaria || ''} | Janela: ${x.janela_avaliacao_dias || 3} dia(s)`
    ).join('\n')
  );
}

if (a.nao_fazer.length) {
  blocos.push(
    'NÃO FAZER AGORA\n' +
    a.nao_fazer.map(x => `- ${x}`).join('\n')
  );
}

return [{
  json: {
    ...$json,
    briefing_gestor: blocos.join('\n\n')
  }
}];
